int parse_age(const std::string& text) {
    int age = std::stoi(text);
    if (age < 0) {
        throw std::runtime_error("An age cannot be negative.");
    }
    if (age > 150) {
        throw std::runtime_error(std::string("Nobody is ") + std::to_string(age) + " years old.");
    }
    return age;
}

